#pragma once

#include <functional>
#include <string>
#include <vector>

// LabCheck: runs all four parts of the lab and prints what each part
// produces. Do not edit this file. Your output must match the expected
// output in the lab handout, character for character.
class LabCheck
{
public:
    // The check runs when you ask for it, and always on GitHub.
    static bool ShouldRun(int argc, char* argv[]);

    // Prints the heading, then runs the four parts in order.
    static void Run();

private:
    // Runs one part, or prints "Not finished yet." when a piece is missing.
    static void RunPart(const std::string& title, std::function<void()> part);

    // Part A: places and finishes orders while the check listens.
    static void PartA();

    // Part B: the pickup screen, the buzzer, and the rewards listen.
    static void PartB();

    // Part C: places two orders and finishes both through the window.
    static void PartC();

    // Part D: checks when each button is enabled, then earns a free drink.
    static void PartD();

    // Prints one result line: the label padded to 32 characters, then the value.
    static void Line(const std::string& label, const std::string& value);

    // Prints one indented result line: the label padded to 30 characters.
    static void InnerLine(const std::string& label, const std::string& value);

    // "1 time" for one, "N times" for any other count.
    static std::string Times(int count);

    // "True" or "False", spelled the way C# prints a bool.
    static std::string tf(bool value);

    // The items with the separator between each pair.
    static std::string Join(const std::vector<std::string>& items, const std::string& separator);

    // Runs one request and reports whether the class refused it.
    static std::string Refused(std::function<void()> request);
};
